    "summary": "・「キャッシュメモリの割り当て方式」の一つ。\n・主記憶のアドレスによって格納されるキャッシュ上の場所が「1箇所に一意に決まる」方式。「構造が簡単」で高速。",
    "keywords": "・フルアソシアティブ\n・セットアソシアティブ\n・ヒット率\n・ライン指定\n・競合ノイズ",
    "analogy": "「コインロッカーの番号固定指定」です。\n「105番の荷物は絶対に105番ロッカーに入れる」と決めておくため、探すのは一瞬ですが、同じロッカーを別の荷物が使うと競合が起きます。",
