    "etymology": "・Direct（直接の、一義的な） ＋ Mapped（割り振られた、対応付けられた）\n➔ 主記憶のアドレス計算によって、格納されるキャッシュ上の場所が直接・一義的に決定（マップ）される方式であることを意味する。",
    "exam": "キャッシュメモリ構造で出題。「割り当て場所が一意に決まる＝ダイレクトマップ」「どこでも格納可能＝フルアソシアティブ」「中間＝セットアソシアティブ」の違いを理解。",
