    "keywords": "・構造ハザード（資源競合）\n・データハザード（依存関係）\n・制御ハザード（分岐命令）\n・分岐予測\n・バイパシング",
    "analogy": "「ベルトコンベアの目詰まり」です。\n前のパーツの塗装が終わるまで次の組み立てができない（データハザード）ように、前の処理待ちでラインがストップしてしまいます。",
